{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "Cefuroxime axetil, a cephalosporin ester prodrug sharing the cephem core, C3 carbamoyloxymethyl group, and C4 ester prodrug motif, has a mean absolute oral bioavailability of 64% in humans, directly supporting F ≥ 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Ampicillin, a beta-lactam with similar polar and ionizable groups, showed 62 ± 17% absolute oral bioavailability in healthy fasting subjects, supporting a high F prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C50"],
      "claim": "Amoxicillin, a close aminopenicillin analogue, showed 93% absolute oral bioavailability at 500 mg in humans, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Loracarbef, a carbacephem beta-lactam, was approximately 90% bioavailable after oral administration in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C62"],
      "claim": "Phenoxymethylpenicillin, a beta-lactam with moderate polarity, had approximately 50% oral bioavailability in normal children, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues—especially the closely related cephalosporin ester cefuroxime axetil (64%) and other orally absorbed beta-lactams such as ampicillin, amoxicillin, loracarbef, and penicillin V—show absolute oral bioavailability well above 20%, supporting a high F prediction for the query.",
  "evidence_gaps": [
    "No direct pharmacokinetic measurement exists for the exact query molecule; the closest analogue, cefuroxime axetil, differs in the C7 side chain and ester promoiety.",
    "The query's C7 hydroxyethyl substituent is not represented in the evidence set, so transfer relies on shared beta-lactam and ester prodrug absorption behavior.",
    "No specific data address possible esterase instability or transporter-mediated efflux of the query's acetoxymethyl ester."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

